    const prompt = `あなたは私の専属トレーニングコーチです。
ユーザーが設定した以下の【マスター台帳】を最優先のルール・文脈として厳守し、親しみやすくモチベーションが上がる言葉遣いで回答してください。
※重要: 台帳の内容（進捗状況など）を更新する必要がある場合は、必ず回答内に \\`\`\`text で囲んだ最新のマスター台帳全文を出力してください。システムがそれを検知して自動保存します。

【マスター台帳】
${myInfo.coachLedger || 'まだ台帳が設定されていません。'}

【私の現在の状態】
・表示名: ${myInfo.displayName || currentUser}
・目標: ${myInfo.goal || '未設定'}
・体重: ${myInfo.weight ? myInfo.weight + 'kg' : '未設定'}
・直近のトレーニング:
${recentWorkoutText || 'まだ記録がありません'}

私のメッセージ:「${userMsg}」`;

    try {
      const response = await fetch('/api/gemini', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error);

      let aiResponse = data.candidates[0].content.parts[0].text;

      // 【自動更新ロジック】台帳のコードブロックを抽出して保存
      const ledgerMatch = aiResponse.match(/```text\n([\s\S]*?)```/);
      if (ledgerMatch && ledgerMatch[1].includes("マスター台帳")) {
         const newLedger = ledgerMatch[1].trim();
